/bin/bash -c "python - <<'PY'
import numpy as np
from PIL import Image
im=np.array(Image.open('first_frame.png')).astype(int)
for y in range(0,52,3):
 row=[]
 for x in range(115,150):
  r,g,b=im[y,x]
  if b-r>30 and b>70: row.append('B')
  elif max(r,g,b)<60: row.append('K')
  elif b-r>12: row.append('b')
  else: row.append('.')
 print(f'{y:02d}',''.join(row))
PY"
